// v2.9.3: 누가 돌아왔는지 — 쉬는 시간 시작 때 접속 중인 플레이어 기준 · 그 PC 토큰에 시계 표시 · 토큰을 누르면 위에 [돌아왔어요] 버튼(토큰 동작)
const BRK_AB = '돌아왔어요', BRK_M = 'stopwatch';
const brkPname = pid => { const p = getObj('player', pid); return p ? (p.get('_displayname') || '?') : '?'; };
const brkChars = pid => findObjs({ type: 'character' }).filter(c => (c.get('controlledby') || '').split(',').includes(pid));
const brkToks = pid => { const ids = new Set(brkChars(pid).map(c => c.id)); return findObjs({ type: 'graphic', subtype: 'token', pageid: Campaign().get('playerpageid') }).filter(t => ids.has(t.get('represents'))); };
const brkMark = (pid, on) => { try { brkToks(pid).forEach(t => setMarker(t, BRK_M, on)); } catch (e) {} };
const brkAbOn = pid => { try { brkChars(pid).forEach(c => { if (!findObjs({ type: 'ability', characterid: c.id, name: BRK_AB })[0]) createObj('ability', { characterid: c.id, name: BRK_AB, action: '!쉬는시간 복귀', istokenaction: true }); }); } catch (e) { log(SCRIPT + ' brk ability: ' + e); } };
const brkAbOff = pid => { try { (pid ? brkChars(pid) : findObjs({ type: 'character' })).forEach(c => findObjs({ type: 'ability', characterid: c.id, name: BRK_AB }).forEach(a => { if (/^!쉬는시간 복귀/.test(a.get('action') || '')) a.remove(); })); } catch (e) {} };
const brkMissClear = () => { (S.brkMiss || []).forEach(pid => { brkMark(pid, false); brkAbOff(pid); }); S.brkMiss = []; };
const brkClear = () => { clearInterval(brkTimer); brkTimer = null; S.brk = null; };

const rang = brkSound();
toAll(box(head('쉬는 시간 끝!', T.green) + body(`<div style="text-align:center;font-size:14px;"><b>다시 시작합니다!</b></div>` +
  (early ? '' : `<div style="text-align:center;font-size:11px;color:${T.muted};">자리로 돌아와 주세요${rang ? ' · 알림음 재생 중' : ''}</div>`), 'padding:6px 10px;')));

const rang = brkSound();
const miss = (b0.expect || []).filter(pid => !(b0.backIds || []).includes(pid));
(b0.backIds || []).forEach(pid => { brkMark(pid, false); brkAbOff(pid); });
S.brkMiss = miss; if (!miss.length) brkAbOff();
toAll(box(head('쉬는 시간 끝!', T.green) + body(`<div style="text-align:center;font-size:14px;"><b>다시 시작합니다!</b></div>` +
  (early ? '' : `<div style="text-align:center;font-size:11px;color:${T.muted};">자리로 돌아와 주세요${rang ? ' · 알림음 재생 중' : ''}</div>`) +
  (miss.length ? `<div style="text-align:center;margin-top:4px;font-size:12px;"><b style="color:${T.red};">아직 안 돌아옴:</b> ${miss.map(p => esc(brkPname(p))).join(', ')}</div><div style="text-align:center;margin-top:3px;">${btn('돌아왔어요', '!쉬는시간 복귀', T.green)}</div>` : ''), 'padding:6px 10px;')));

if (!S.brk) return;
brkClear();
doPause(false, true);

if (!S.brk) return;
const b0 = S.brk;
brkClear();
doPause(false, true);

brkMissClear(); brkAbOff();
const expect = findObjs({ _type: 'player' }).filter(p => p.get('_online') && !playerIsGM(p.id)).map(p => p.id);
S.brk = { min, end, back: [], backIds: [], expect, warned: end - Date.now() <= 60000 };
expect.forEach(pid => { brkMark(pid, true); brkAbOn(pid); });

if (!S.brk) return toWho(msg, line('', '지금은 쉬는 시간이 아니에요.', '#777'));
const who = msg.who.replace(/ \(GM\)$/, '');
if (!S.brk.back.includes(who)) S.brk.back.push(who);
toAll(line('', `<b>${esc(who)}</b> 돌아왔어요 (${S.brk.back.length}명)`, T.green));
return;

const pid = msg.playerid, who = playerIsGM(pid) ? msg.who.replace(/ \(GM\)$/, '') : brkPname(pid);
if (!S.brk) {   // 쉬는 시간이 끝난 뒤 늦게 돌아온 사람
  if ((S.brkMiss || []).includes(pid)) { S.brkMiss = S.brkMiss.filter(x => x !== pid); brkMark(pid, false); brkAbOff(pid);
    toAll(line('', `<b>${esc(who)}</b> 돌아왔어요${S.brkMiss.length ? ` <span style="font-size:11px;">(아직: ${S.brkMiss.map(p => esc(brkPname(p))).join(', ')})</span>` : ' — 모두 돌아왔어요'}`, T.green)); return; }
  return toWho(msg, line('', '지금은 쉬는 시간이 아니에요.', '#777'));
}
S.brk.backIds = S.brk.backIds || []; if (!S.brk.backIds.includes(pid)) S.brk.backIds.push(pid);
if (!S.brk.back.includes(who)) S.brk.back.push(who);
brkMark(pid, false); brkAbOff(pid);
const left = (S.brk.expect || []).filter(x => !S.brk.backIds.includes(x));
toAll(line('', `<b>${esc(who)}</b> 돌아왔어요 (${S.brk.back.length}명)${left.length ? ` <span style="font-size:11px;">· 아직: ${left.map(p => esc(brkPname(p))).join(', ')}</span>` : ' · 모두 돌아왔어요'}`, T.green));
return;

const left = S.brk.end - Date.now();
if (left <= 0) {   // v2.9.3: 다 안 돌아왔으면 자동 재개하지 않고 GM의 [지금 재개]를 기다려요
  const miss = (S.brk.expect || []).filter(pid => !(S.brk.backIds || []).includes(pid));
  if (!miss.length) return brkEnd(false);
  if (!S.brk.over) { S.brk.over = true; const rang = brkSound();
    toAll(box(head('쉬는 시간 끝', '#6b4a2a') + body(`<div style="text-align:center;font-size:13px;">아직 안 돌아온 사람을 기다려요${rang ? ' · 알림음 재생 중' : ''}</div><div style="text-align:center;margin-top:3px;font-size:12px;"><b style="color:${T.red};">아직:</b> ${miss.map(p => esc(brkPname(p))).join(', ')}</div><div style="text-align:center;margin-top:4px;">${btn('돌아왔어요', '!쉬는시간 복귀', T.green)}</div>`, 'padding:6px 10px;')));
    toGM(line('', `시간이 끝났지만 아직 안 돌아옴: ${miss.map(p => esc(brkPname(p))).join(', ')} — 누르기 전까지 일시정지 유지 ${btn('지금 재개', '!쉬는시간 끝', T.green)}`, '#6b4a2a')); }
  return brkSetText();
}

toAll(line('', `<b>${esc(who)}</b> 돌아왔어요 (${S.brk.back.length}명)${left.length ? ` <span style="font-size:11px;">· 아직: ${left.map(p => esc(brkPname(p))).join(', ')}</span>` : ' · 모두 돌아왔어요'}`, T.green));
if (!left.length && S.brk.over) toGM(line('', `모두 돌아왔어요 ${btn('지금 재개', '!쉬는시간 끝', T.green)}`, '#6b4a2a'));
return;
